import { createEffect, createSignal, Show, type Component } from "solid-js";

import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { RingMeter } from "#core/ui-next/components/ring-meter.jsx";
import { TooltipKeyword } from "#core/ui-next/components/tooltip-keyword.jsx";
import { Tooltip, TooltipHorizontalPosition, TooltipVerticalPosition } from "#core/ui-next/components/tooltip.jsx";

import { EntryDivider, TicketRow, TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";

export interface CityBannerPopulationProps {
	/** The city this population ring represents, or `null` while the banner is still initializing. */
	cityID: ComponentID | null;
	population: number;
	currentFood: number;
	foodPerTurn: number;
	canGrow: boolean;
}

export const CityBannerPopulation: Component<CityBannerPopulationProps> = (props) => {
	const [isValid, setIsValid] = createSignal(false);
	const [canGrow, setCanGrow] = createSignal(false);

	const [currentPopulation, setCurrentPopulation] = createSignal(-1);
	const [urbanPop, setUrbanPop] = createSignal(-1);
	const [ruralPop, setRuralPop] = createSignal(-1);
	const [workerPop, setWorkerPop] = createSignal(-1);

	const [turnsUntilGrowth, setTurnsUntilGrowth] = createSignal(-1);
	const [currentFood, setCurrentFood] = createSignal(-1);
	const [currentThreshold, setCurrentThreshold] = createSignal(24);
	const [foodPerTurn, setFoodPerTurn] = createSignal(0);

	const truncateDecimal = (input: number) => {
		return input >= 1000 ? Math.floor(input) : input;
	};

	createEffect(() => {
		const cityID = props.cityID;
		if (!cityID || !ComponentID.isValid(cityID)) {
			setIsValid(false);
			return;
		}

		const city = Cities.get(cityID);
		if (!city) {
			setIsValid(false);
			return;
		}

		const cityGrowth = city.Growth;
		if (!cityGrowth) {
			setIsValid(false);
			return;
		}

		setIsValid(true);
		setCanGrow(props.canGrow);

		setCurrentPopulation(props.population);
		setUrbanPop(city.urbanPopulation);
		setRuralPop(city.ruralPopulation);
		setWorkerPop(city.Workers?.getNumWorkers(false) ?? 0);

		setCurrentFood(truncateDecimal(props.currentFood));
		setFoodPerTurn(truncateDecimal(props.foodPerTurn));
		setTurnsUntilGrowth(cityGrowth.turnsUntilGrowth);
		setCurrentThreshold(truncateDecimal(cityGrowth.getNextGrowthFoodThreshold().value));
	});

	return (
		<Show when={isValid()}>
			<Tooltip
				initialVPosition={TooltipVerticalPosition.BOTTOM}
				initialHPosition={TooltipHorizontalPosition.RIGHT}
				offset={22}
				allowFlip={true}
			>
				{/* -------------------------------------------------------------------
					Progress Circle on Banner
				------------------------------------------------------------------- */}
				<Tooltip.Trigger>
					<div class="items-center justify-center w-6 h-6 relative">
						<RingMeter
							min={0}
							max={currentThreshold()}
							value={currentFood()}
							class="city-banner__ring city-banner__population-ring bg-cover bg-center flex size-9 self-center align-center"
						>
							<div
								class="city-banner__population-number font-body-xs text-white top-0 w-full text-center pointer-events-auto"
								aria-label={Locale.compose(`{LOC_CAPITAL_SELECT_POPULATION} ${currentPopulation()},`)}
							>
								{currentPopulation()}
							</div>
						</RingMeter>
						<Show when={turnsUntilGrowth() >= 0 && canGrow()}>
							<div class="city-banner__turn flex flex-col relative justify-end align-center self-center w-8 mt-0-\\.5 pointer-events-none">
								<div
									class="city-banner__turn-number font-body-xs text-white text-center w-full bg-cover bg-center bg-no-repeat"
									aria-label={Locale.compose(
										"LOC_UI_CITY_DETAILS_NEW_CITIZEN_IN_TURNS",
										turnsUntilGrowth(),
									)}
								>
									{turnsUntilGrowth()}
								</div>
							</div>
						</Show>
					</div>
				</Tooltip.Trigger>
				{/* -------------------------------------------------------------------
					Tooltip
				------------------------------------------------------------------- */}
				<Tooltip.Content>
					<Tooltip.Frame class="w-auto min-w-62 max-w-84 self-start text-sm">
						<div
							class="size-16 relative self-center -mt-12 -mb-6 flex flex-col items-center justify-center bg-cover bg-center bg-no-repeat pointer-events-none"
							style={{ "background-image": "url(blp:base_triumph_ring)" }}
						>
							<RingMeter
								class="size-11 absolute flex justify-center bg-contain bg-center flex-auto items-center"
								min={0}
								max={currentThreshold()}
								value={currentFood()}
								animationDuration={1}
								ringImage={`url("blp:progress_ring_triumph")`}
								ringTint="rgba(73, 209, 130, 1)"
							>
								<div class="font-title-lg font-bold">{currentPopulation()}</div>
							</RingMeter>
						</div>
						<div class="w-full h-6" />
						<div class="flex flex-col items-stretch justify-center">
							<L10n.Stylize
								class="text-secondary text-center uppercase font-title"
								text={"LOC_UI_CITY_DETAILS_GROWTH_TAB"}
							/>

							<Show
								when={canGrow()}
								fallback={
									<div class="flex items-center justify-center">
										<L10n.Stylize
											class="text-accent-3 text-sm"
											text={"LOC_UI_CITY_DETAILS_TOWN_NO_GROWTH"}
										/>
									</div>
								}
							>
								<>
									<TicketSection class="flex flex-col">
										<L10n.Stylize
											class="text-accent-3 text-xs text-center"
											args={[currentFood(), currentThreshold(), foodPerTurn(), "YIELD_FOOD"]}
											text={"LOC_UI_CITY_BANNER_YIELD_BREAKDOWN"}
										/>
										{/* Commented out until Efficiencies are sorted out on the engineering side */}
										{/* <L10n.Stylize
											class="text-accent-3 text-xs text-center"
											args={[999, 999]}
											text={"LOC_UI_CITY_BANNER_YIELD_GROWTH_RATE_BONUS"}
										/> */}
										<EntryDivider />
										<L10n.Stylize
											class="text-xs text-center"
											args={[turnsUntilGrowth()]}
											text={"LOC_UI_CITY_DETAILS_NEW_CITIZEN_IN_TURNS"}
										/>
									</TicketSection>
									<L10n.Stylize
										class="text-secondary text-xs text-center uppercase font-title mt-2"
										text={"LOC_CAPITAL_SELECT_POPULATION"}
									/>
								</>
							</Show>
						</div>
						<TicketSection>
							<TicketRow
								icon={
									<Icon
										class="size-6"
										name={"CITY_URBAN"}
									/>
								}
							>
								<div class="flex flex-row justify-between items-center">
									<Tooltip.Text text="LOC_UI_CITY_DETAILS_URBAN_POPULATION_TOOLTIP">
										<TooltipKeyword>
											<L10n.Stylize
												class="font-title text-sm"
												text={"LOC_UI_CITY_STATUS_URBAN_POPULATION"}
											/>
										</TooltipKeyword>
									</Tooltip.Text>
									<div class="h-px w-4" />
									<div class="text-sm">{urbanPop()}</div>
								</div>
							</TicketRow>
							<EntryDivider />
							<TicketRow
								icon={
									<Icon
										class="size-6"
										name={"CITY_RURAL"}
									/>
								}
							>
								<div class="flex flex-row justify-between items-center">
									<Tooltip.Text text="LOC_UI_CITY_DETAILS_RURAL_POPULATION_TOOLTIP">
										<TooltipKeyword>
											<L10n.Stylize
												class="font-title text-sm"
												text={"LOC_UI_CITY_STATUS_RURAL_POPULATION"}
											/>
										</TooltipKeyword>
									</Tooltip.Text>
									<div class="h-px w-4" />
									<div class="text-sm">{ruralPop()}</div>
								</div>
							</TicketRow>
							<EntryDivider />
							<TicketRow
								icon={
									<Icon
										class="size-6"
										name={"SPECIALIST"}
									/>
								}
							>
								<div class="flex flex-row justify-between items-center">
									<Tooltip.Text text="LOC_UI_CITY_DETAILS_SPECIALIST_POPULATION_TOOLTIP">
										<TooltipKeyword>
											<L10n.Stylize
												class="font-title text-sm"
												text={"LOC_WORKERS_TITLE"}
											/>
										</TooltipKeyword>
									</Tooltip.Text>
									<div class="h-px w-4" />
									<div class="text-sm">{workerPop()}</div>
								</div>
							</TicketRow>
						</TicketSection>
					</Tooltip.Frame>
				</Tooltip.Content>
			</Tooltip>
		</Show>
	);
};

defineLegacyComponent(
	"city-banner-population",
	{
		attrs: {
			"data-cityid": null,
			"data-population": "-1",
			"data-current-food": "-1",
			"data-food-per-turn": "-1",
			"data-can-grow": "true",
		},
	},
	(attrs) => (
		<CityBannerPopulation
			cityID={attrs["data-cityid"] ? (JSON.parse(attrs["data-cityid"]) as ComponentID) : null}
			population={Number(attrs["data-population"])}
			currentFood={Number(attrs["data-current-food"])}
			foodPerTurn={Number(attrs["data-food-per-turn"])}
			canGrow={attrs["data-can-grow"] == "true"}
		/>
	),
);
